import std.collection.ArrayList

class BoyerMooreSearch {

    let text: String
    let pattern: String
    let textLen: Int64
    let patLen: Int64

    public init(text: String, pattern: String) {
        this.text = text
        this.pattern = pattern
        this.textLen = text.size
        this.patLen = pattern.size
    }

    public func match_in_pattern(char: String): Int64 {
        for (i in this.patLen - 1..-1..-1) {
            if (this.pattern[i] == char[0]) {
                return i
            }
        }
        return -1
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        for (i in this.patLen - 1..-1..-1) {
            if (currentPos + i >= this.textLen || this.pattern[i] != this.text[currentPos + i]) {
                return i
            }
        }
        return -1
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        let res = ArrayList<Int64>()
        var i = 0
        while (i <= this.textLen - this.patLen) {
            let mismatch = this.mismatch_in_text(i)
            if (mismatch == -1) {
                res.append(i)
                i += 1
            } else {
                let badChar = this.text[i + mismatch]
                let shift = mismatch - this.match_in_pattern(badChar.toString())
                i += max(1, shift)
            }
        }
        return res
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.convert.Parsable

class Calculator {

    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64, y: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        let operand_stack = ArrayList<Float64>()
        let operator_stack = ArrayList<String>()
        let i = 0
        let n = expression.size
        while (i < n) {
            let c = expression[i]
            if (c >= '0' && c <= '.') {
                let num = 0.0
                let j = i
                while (j < n && ((expression[j] >= '0' && expression[j] <= '9') || expression[j] == '.')) {
                    j += 1
                }
                num = Float64.parse(expression[i..j])
                operand_stack.append(num)
                i = j
                continue
            } else if (c == '(') {
                operator_stack.append("(")
            } else if (c == ')') {
                while (operator_stack.size > 0 && operator_stack[operator_stack.size - 1] != "(") {
                    let (new_ops, new_ors) = apply_operator(operand_stack, operator_stack)
                    operand_stack.clear()
                    operand_stack.extend(new_ops)
                    operator_stack.clear()
                    operator_stack.extend(new_ors)
                }
                if (operator_stack.size > 0) {
                    operator_stack.removeAt(operator_stack.size - 1)
                }
            } else if (operators.contains(c.toString())) {
                while (operator_stack.size > 0 &&
                       operator_stack[operator_stack.size - 1] != "(" &&
                       precedence(operator_stack[operator_stack.size - 1]) >= precedence(c.toString())) {
                    let (new_ops, new_ors) = apply_operator(operand_stack, operator_stack)
                    operand_stack.clear()
                    operand_stack.extend(new_ops)
                    operator_stack.clear()
                    operator_stack.extend(new_ors)
                }
                operator_stack.append(c.toString())
            }
            i += 1
        }
        while (operator_stack.size > 0) {
            let (new_ops, new_ors) = apply_operator(operand_stack, operator_stack)
            operand_stack.clear()
            operand_stack.extend(new_ops)
            operator_stack.clear()
            operator_stack.extend(new_ors)
        }
        if (operand_stack.size == 1) {
            return Some(operand_stack[0])
        } else {
            return None
        }
    }

    public func precedence(op: String): Int64 {
        if (op == "+" || op == "-") {
            return 1
        } else if (op == "*" || op == "/") {
            return 2
        } else if (op == "^") {
            return 3
        } else {
            return 0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        let op = operator_stack[operator_stack.size - 1]
        operator_stack.removeAt(operator_stack.size - 1)
        let b = operand_stack[operand_stack.size - 1]
        operand_stack.removeAt(operand_stack.size - 1)
        let a = operand_stack[operand_stack.size - 1]
        operand_stack.removeAt(operand_stack.size - 1)
        let func = operators.get(op)
        let res = func(a, b)
        operand_stack.append(res)
        return (operand_stack, operator_stack)
    }
}

