class CalendarUtil {
    let events: ArrayList<Event>

    public init() {
        this.events = ArrayList<Event>()
    }

    public func add_event(event: Event): Unit {
        this.events.append(event)
    }

    public func remove_event(event: Event): Unit {
        this.events.remove(event)
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let result = ArrayList<Event>()
        for (e in this.events) {
            if (e.date == date) {
                result.append(e)
            }
        }
        return result
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        for (e in this.events) {
            if (e.date == start_time && e.date == end_time) {
                if (!(end_time <= e.start_time || start_time >= e.end_time)) {
                    return false
                }
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        let slots = ArrayList<(DateTime, DateTime)>()
        let dayStart = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 0, minute: 0)
        let dayEnd = dayStart.add(Duration.of(hours: 24))
        var current = dayStart
        for (e in this.events) {
            if (e.date == date) {
                if (current < e.start_time) {
                    slots.append((current, e.start_time))
                }
                current = e.end_time
            }
        }
        if (current < dayEnd) {
            slots.append((current, dayEnd))
        }
        return slots
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let now = DateTime.now()
        let sorted = this.events.filter(e => e.date >= now)
                              .sortedBy(e => (e.date, e.start_time))
        let result = ArrayList<Event>()
        for (i in 0..sorted.size()) {
            if (i >= num_events) {
                break
            }
            result.append(sorted[i])
        }
        return result
    }
}

import std.collection.HashMap

class CamelCaseMap {

    let _data: HashMap<String, Any>

    public init() {
        _data = HashMap<String, Any>()
    }

    public func __getitem__(key: String): Any {
        let camelKey = CamelCaseMap._to_camel_case(key)
        _data[camelKey]
    }

    public func __setitem__(key: String, value: Any): Unit {
        let camelKey = CamelCaseMap._to_camel_case(key)
        _data[camelKey] = value
    }

    public func __delitem__(key: String): Unit {
        let camelKey = CamelCaseMap._to_camel_case(key)
        _data.remove(camelKey)
    }

    public func __len__(): Int64 {
        _data.size()
    }

    public func _convert_key(key: Any): Any {
        match (key) {
            case s: String => CamelCaseMap._to_camel_case(s)
            case _ => key
        }
    }

    public static func _to_camel_case(key: String): String {
        let parts = key.split('_')
        var result = ""
        for (i in 0..parts.size) {
            if (i == 0) {
                result += parts[i]
            } else if (parts[i].size > 0) {
                result += parts[i][0].toUpperCase() + parts[i].substring(1)
            }
        }
        result
    }
}

import std.collection.ArrayList

class ChandrasekharSieve {

    let n: Int64
    var primes: ArrayList<Int64> = ArrayList<Int64>()

    public init(n: Int64) {
        this.n = n
        this.primes = generate_primes()
    }

    public func generate_primes(): ArrayList<Int64> {
        if (n < 2) {
            return ArrayList<Int64>()
        }
        var sieve = Array<Bool>(n + 1, item: true)
        sieve[0] = false
        sieve[1] = false
        var p: Int64 = 2
        while (p * p <= n) {
            if (sieve[p]) {
                var i = p * p
                while (i <= n) {
                    sieve[i] = false
                    i += p
                }
            }
            p += 1
        }
        var result = ArrayList<Int64>()
        for (i in 2..=n) {
            if (sieve[i]) {
                result.append(i)
            }
        }
        return result
    }

    public func get_primes(): ArrayList<Int64> {
        return primes
    }
}

