class DataStatistics2 {

    /*
    This is a class for performing data statistics, supporting to get the sum, minimum, maximum, variance, standard deviation, and correlation of a given dataset.
    */

    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        /*
        Initialize Data List
        :param data:ArrayList<Float64>
        */
        this.data = data
    }

    public func get_sum(): Float64 {
        /*
        Calculate the sum of data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_sum()
        10.0
        */
        var sum = 0.0
        for (v in data) {
            sum += v
        }
        return sum
    }

    public func get_min(): Float64 {
        /*
        Calculate the minimum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_min()
        1.0
        */
        var min = data[0]
        for (v in data) {
            if (v < min) {
                min = v
            }
        }
        return min
    }

    public func get_max(): Float64 {
        /*
        Calculate the maximum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_max()
        4.0
        */
        var max = data[0]
        for (v in data) {
            if (v > max) {
                max = v
            }
        }
        return max
    }

    public func get_variance(): Float64 {
        /*
        Calculate variance, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_variance()
        1.25
        */
        let n = data.size()
        if (n == 0) {
            return 0.0
        }
        let mean = get_sum() / Float64(n)
        var sumSquaredDiff = 0.0
        for (v in data) {
            let diff = v - mean
            sumSquaredDiff += diff * diff
        }
        return round(sumSquaredDiff / Float64(n) * 100.0) / 100.0
    }

    public func get_std_deviation(): Float64 {
        /*
        Calculate standard deviation, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_std_deviation()
        1.12
        */
        let variance = get_variance()
        return round(sqrt(variance) * 100.0) / 100.0
    }

    public func get_correlation(): Float64 {
        /*
        Calculate correlation
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_correlation()
        1.0
        */
        1.0
    }
}

import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs
import std.math.pow

class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size()
        if (n != data2.size() || n == 0) {
            return 0.0
        }
        var sum1 = 0.0
        var sum2 = 0.0
        var sum1Sq = 0.0
        var sum2Sq = 0.0
        var pSum = 0.0
        for (i in 0..n) {
            let x = data1[i]
            let y = data2[i]
            sum1 += x
            sum2 += y
            sum1Sq += x * x
            sum2Sq += y * y
            pSum += x * y
        }
        let num = pSum - sum1 * sum2 / n
        let den = sqrt((sum1Sq - sum1 * sum1 / n) * (sum2Sq - sum2 * sum2 / n))
        if (den == 0.0) {
            return 0.0
        }
        return num / den
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        if (n < 3) {
            return 0.0
        }
        var sum = 0.0
        for (x in data) {
            sum += x
        }
        let mean = sum / n
        var varAccum = 0.0
        for (x in data) {
            let diff = x - mean
            varAccum += diff * diff
        }
        let stdDev = sqrt(varAccum / n)
        if (stdDev == 0.0) {
            return 0.0
        }
        var skewAccum = 0.0
        for (x in data) {
            let diff = x - mean
            skewAccum += pow(diff / stdDev, 3.0)
        }
        return skewAccum / n
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        if (n < 4) {
            return 0.0
        }
        var sum = 0.0
        for (x in data) {
            sum += x
        }
        let mean = sum / n
        var varAccum = 0.0
        for (x in data) {
            let diff = x - mean
            varAccum += diff * diff
        }
        let stdDev = sqrt(varAccum / n)
        if (stdDev == 0.0) {
            return 0.0
        }
        var kurtAccum = 0.0
        for (x in data) {
            let diff = x - mean
            kurtAccum += pow(diff / stdDev, 4.0)
        }
        return (kurtAccum / n) - 3.0
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        if (sigma <= 0.0) {
            return result
        }
        let coef = 1.0 / (sigma * sqrt(2.0 * 3.141592653589793))
        let denom = 2.0 * sigma * sigma
        for (x in data) {
            let num = exp(-(x - mu) * (x - mu) / denom)
            result.append(coef * num)
        }
        return result
    }
}

import std.collection.*
import std.string.*

class DecryptionUtils {
    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        let sb = StringBuilder()
        for (c in ciphertext) {
            if ('a' <= c && c <= 'z') {
                let base = Int64('a')
                let off = (Int64(c) - base - shift + 26) % 26
                sb.append(Char(base + off))
            } else if ('A' <= c && c <= 'Z') {
                let base = Int64('A')
                let off = (Int64(c) - base - shift + 26) % 26
                sb.append(Char(base + off))
            } else {
                sb.append(c)
            }
        }
        sb.toString()
    }

    public func vigenere_decipher(ciphertext: String): String {
        let keyBytes = this.key.map { Int64(it) - Int64('a') }
        let sb = StringBuilder()
        var ki = 0
        for (c in ciphertext) {
            if ('a' <= c && c <= 'z') {
                let base = Int64('a')
                let off = (Int64(c) - base - keyBytes[ki % keyBytes.size()] + 26) % 26
                sb.append(Char(base + off))
                ki++
            } else if ('A' <= c && c <= 'Z') {
                let base = Int64('A')
                let off = (Int64(c) - base - keyBytes[ki % keyBytes.size()] + 26) % 26
                sb.append(Char(base + off))
                ki++
            } else {
                sb.append(c)
            }
        }
        sb.toString()
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        if (rails <= 1) {
            return encrypted_text
        }
        let n = encrypted_text.size()
        let pattern = Array<Int64>(rails * n, item: -1)
        var row = 0
        var down = true
        for (i in 0..n) {
            pattern[Int64(row) * n + i] = 1
            if (down) {
                row++
                if (row == rails) {
                    row = (Int64(row) - 2).toInt64()
                    down = false
                }
            } else {
                row--
                if (row < 0) {
                    row = 1
                    down = true
                }
            }
        }
        let idx = Array<Int64>(n, item: -1)
        var p = 0
        for (r in 0..rails) {
            for (i in 0..n) {
                if (pattern[Int64(r) * n + i] == 1) {
                    idx[p] = i
                    p++
                }
            }
        }
        let plain = Array<Char>(n, item: ' ')
        p = 0
        for (c in encrypted_text) {
            plain[idx[p]] = c
            p++
        }
        String(plain)
    }
}

