        }
        return list
    }
}

import std.collection.ArrayList

class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let n = x.size()
        let m = x_interp.size()
        let result = ArrayList<Float64>()
        for (i in 0..m) {
            let xi = x_interp[i]
            if (xi <= x[0]) {
                result.append(y[0])
                continue
            }
            if (xi >= x[n-1]) {
                result.append(y[n-1])
                continue
            }
            for (j in 0..(n-1)) {
                if (xi >= x[j] && xi <= x[j+1]) {
                    let t = (xi - x[j]) / (x[j+1] - x[j])
                    let yi = y[j] + t * (y[j+1] - y[j])
                    result.append(yi)
                    break
                }
            }
        }
        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let nx = x.size()
        let ny = y.size()
        let m = x_interp.size()
        let result = ArrayList<Float64>()
        for (k in 0..m) {
            let xi = x_interp[k]
            let yi = y_interp[k]
            var x0 = 0
            var x1 = 0
            var y0 = 0
            var y1 = 0
            if (xi <= x[0]) {
                x0 = 0
                x1 = 0
            } else if (xi >= x[nx-1]) {
                x0 = nx - 1
                x1 = nx - 1
            } else {
                for (i in 0..(nx-1)) {
                    if (xi >= x[i] && xi <= x[i+1]) {
                        x0 = i
                        x1 = i + 1
                        break
                    }
                }
            }
            if (yi <= y[0]) {
                y0 = 0
                y1 = 0
            } else if (yi >= y[ny-1]) {
                y0 = ny - 1
                y1 = ny - 1
            } else {
                for (j in 0..(ny-1)) {
                    if (yi >= y[j] && yi <= y[j+1]) {
                        y0 = j
                        y1 = j + 1
                        break
                    }
                }
            }
            let fx_y0: Float64
            let fx_y1: Float64
            if (x0 == x1) {
                fx_y0 = z[x0][y0]
                fx_y1 = z[x0][y1]
            } else {
                let t_x = (xi - x[x0]) / (x[x1] - x[x0])
                fx_y0 = z[x0][y0] + t_x * (z[x1][y0] - z[x0][y0])
                fx_y1 = z[x0][y1] + t_x * (z[x1][y1] - z[x0][y1])
            }
            let zi: Float64
            if (y0 == y1) {
                zi = fx_y0
            } else {
                let t_y = (yi - y[y0]) / (y[y1] - y[y0])
                zi = fx_y0 + t_y * (fx_y1 - fx_y0)
            }
            result.append(zi)
        }
        return result
    }
}

import std.convert.Parsable
import std.convert.Formattable
import std.collection.ArrayList

class IPAddress {

    /*
    This is a class to process IP Address, including validating, getting the octets and obtaining the binary representation of a valid IP address.
    */

    let ip_address: String

    public init(ip_address: String) {
        /*
        Initialize the IP address to the specified address
        :param ip_address:String
        */
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        /*
        Judge whether the IP address is valid, that is, whether the IP address is composed of four Decimal digits separated by '.'. Each digit is greater than or equal to 0 and less than or equal to 255
        :return: Bool
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.is_valid()
        true
        */
        let parts = ip_address.split('.')
        if (parts.size != 4) {
            return false
        }
        for (p in parts) {
            if (p.size == 0) {
                return false
            }
            if (p[0] == '0' && p.size != 1) {
                return false
            }
            let num = UInt8.fromString(p)
            if (num is None) {
                return false
            }
            if (UInt8.fromString(p).get() > 255) {
                return false
            }
        }
        true
    }

    public func get_octets(): ArrayList<String> {
        /*
        If the IP address is valid, the list of four decimal numbers separated by "." constituting the IP address is returned; otherwise, an empty list is returned
        :return: ArrayList<String>
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.get_octets()
        ["10", "10", "10", "10"]
        */
        if (!this.is_valid()) {
            return ArrayList<String>()
        }
        let parts = this.ip_address.split('.')
        let list = ArrayList<String>()
        for (p in parts) {
            list.append(p)
        }
        list
    }

    public func get_binary(): String {
        /*
        If the IP address is valid, return the binary form of the IP address; otherwise, return ''
        :return: String
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.get_binary()
        "00001010.00001010.00001010.00001010"
        */
        if (!this.is_valid()) {
            return ""
        }
        let parts = this.ip_address.split('.')
        let result = StringBuilder()
        for (i in 0..parts.size) {
            let num = UInt8.fromString(parts[i]).get()
            let bin = num.toString(radix: 2, lowercase: true)
            let padded = bin.padStart(8, '0')
            result.append(padded)
            if (i < parts.size - 1) {
                result.append('.')
            }
        }
        result.toString()
    }
}

import std.net.IPAddress
import std.posix.gethostname
import std.net.Dns
