class IpUtil {

    public static func is_valid_ipv4(ip_address: String): Bool {
        let parts = ip_address.split('.')
        if (parts.size() != 4) {
            return false
        }
        for (part in parts) {
            match (UInt64.parse(part)) {
                case Some(num) => if (num > 255) { return false }
                case None => return false
            }
        }
        return true
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        let reg = Regex("^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$")
        return reg != None && reg!.matches(ip_address)
    }

    public static func get_hostname(ip_address: String): Option<String> {
        let addr = IPAddress.parse(ip_address)
        match (addr) {
            case Some(ip) => {
                let host = Dns.getHostByAddr(ip)
                return host
            }
            case None => return None
        }
    }
}

