class JobMarketplace {
    let jobListings: ArrayList<JobListing>
    let resumes: ArrayList<Resume>

    public init() {
        this.jobListings = ArrayList<JobListing>()
        this.resumes = ArrayList<Resume>()
    }

    public func post_job(job_title: String, company: String, requirements: ArrayList<String>): Unit {
        jobListings.append(JobListing(job_title, company, requirements))
    }

    public func remove_job(job: JobListing): Unit {
        jobListings.remove(job)
    }

    public func submit_resume(name: String, skills: ArrayList<String>, experience: String): Unit {
        resumes.append(Resume(name, skills, experience))
    }

    public func withdraw_resume(resume: Resume): Unit {
        resumes.remove(resume)
    }

    public func search_jobs(criteria: String): ArrayList<JobListing> {
        let result = ArrayList<JobListing>()
        for (job in jobListings) {
            for (req in job.requirements) {
                if (req.contains(criteria)) {
                    result.append(job)
                    break
                }
            }
        }
        return result
    }

    public func get_job_applicants(job: JobListing): ArrayList<Resume> {
        let qualified = ArrayList<Resume>()
        for (resume in resumes) {
            if (JobMarketplace.matches_requirements(resume, job.requirements)) {
                qualified.append(resume)
            }
        }
        return qualified
    }

    public static func matches_requirements(resume: Resume, requirements: ArrayList<String>): Bool {
        for (req in requirements) {
            var found = false
            for (skill in resume.skills) {
                if (skill == req) {
                    found = true
                    break
                }
            }
            if (!found) {
                return false
            }
        }
        return true
    }
}

import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        let po = observe(testData, k)
        let pe = expect(testData, k)
        if (1.0 - pe).abs() < 1e-12 {
            return 0.0
        }
        return (po - pe) / (1.0 - pe)
    }

    private static func observe(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var sumDiag = 0.0
        var total = 0.0
        for (i in 0..testData.size) {
            let row = testData[i]
            for (j in 0..k) {
                let v = row[j].toFloat64()
                if i == j {
                    sumDiag += v
                }
                total += v
            }
        }
        return sumDiag / total
    }

    private static func expect(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var rowSum = Array<Float64>(k, item: 0.0)
        var colSum = Array<Float64>(k, item: 0.0)
        var total = 0.0
        for (i in 0..testData.size) {
            let row = testData[i]
            for (j in 0..k) {
                let v = row[j].toFloat64()
                rowSum[i] += v
                colSum[j] += v
                total += v
            }
        }
        var pe = 0.0
        for (i in 0..k) {
            pe += (rowSum[i] * colSum[i]) / (total * total)
        }
        return pe
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        let total = N * n
        var p = Array<Float64>(k, item: 0.0)
        for (j in 0..k) {
            var cj = 0
            for (i in 0..N) {
                cj += testData[i][j]
            }
            p[j] = cj.toFloat64() / total.toFloat64()
        }
        var Pbar = 0.0
        for (i in 0..N) {
            var sumsq = 0.0
            for (j in 0..k) {
                let x = testData[i][j].toFloat64()
                sumsq += x * x
            }
            Pbar += (sumsq - n.toFloat64()) / (n.toFloat64() * (n.toFloat64() - 1.0))
        }
        Pbar = Pbar / N.toFloat64()
        let Pe = p.map { x => x * x }.reduce((a, b) => a + b, 0.0)
        if (1.0 - Pe).abs() < 1e-12 {
            return 0.0
        }
        return (Pbar - Pe) / (1.0 - Pe)
    }
}

