import std.collection.ArrayList
import std.collection.HashSet
import std.random.Random

class MahjongConnect {

    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]
        let iconCount = ICONS.size()
        let board = ArrayList<ArrayList<String>>()
        let rng = Random()
        for (_ in 0..rows) {
            let row = ArrayList<String>()
            for (_ in 0..cols) {
                let index = rng.nextInt64(iconCount)
                row.append(ICONS[index])
            }
            board.append(row)
        }
        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]
        if (x1 < 0 || x1 >= rows || y1 < 0 || y1 >= cols ||
            x2 < 0 || x2 >= rows || y2 < 0 || y2 >= cols) {
            return false
        }
        if (pos1 == pos2) {
            return false
        }
        if (board[x1][y1] != board[x2][y2]) {
            return false
        }
        return has_path(pos1, pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let visited = ArrayList<(Int64, Int64)>()
        return dfs(pos1, pos2, visited, 0)
    }

    private func dfs(current: (Int64, Int64), target: (Int64, Int64), visited: ArrayList<(Int64, Int64)>, turns: Int64): Bool {
        if (turns > 2) {
            return false
        }
        if (current == target) {
            return true
        }
        if (contains(visited, current)) {
            return false
        }
        visited.append(current)
        let (x, y) = current
        let directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for (dir in directions) {
            let (dx, dy) = dir
            let nx = x + dx
            let ny = y + dy
            if (nx >= 0 && nx < BOARD_SIZE[0] && ny >= 0 && ny < BOARD_SIZE[1]) {
                if ((nx, ny) == target) {
                    return true
                }
                if (board[nx][ny] == " ") {
                    if (dfs((nx, ny), target, visited, turns)) {
                        return true
                    }
                }
            } else {
                if (dfs((nx, ny), target, visited, turns + 1)) {
                    return true
                }
            }
        }
        visited.pop_back()
        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        board[x1][y1] = " "
        board[x2][y2] = " "
    }

    public func is_game_over(): Bool {
        for (row in board) {
            for (cell in row) {
                if (cell != " ") {
                    return false
                }
            }
        }
        return true
    }
}

class Manacher {

    let input_string: String

    public init(input_string: String) {
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        let left = center - diff
        let right = center + diff
        if (left < 0 || right >= string.size) {
            return diff - 1
        }
        if (string[left] != string[right]) {
            return diff - 1
        }
        return palindromic_length(center, diff + 1, string)
    }

    public func palindromic_string(): String {
        if (input_string.size == 0) {
            return ""
        }
        var t = StringBuilder()
        t.append("|")
        for (c in input_string) {
            t.append(c)
            t.append("|")
        }
        let s = t.toString()
        var maxLen: Int64 = 0
        var center: Int64 = 0
        for (i in 0..s.size) {
            let len = palindromic_length(i, 1, s)
            if (len > maxLen) {
                maxLen = len
                center = i
            }
        }
        var start = (center - maxLen) / 2
        return input_string[start..start + maxLen]
    }
}

import std.collection.ArrayList
import std.math.abs

class MetricsCalculator {

    /*
    The class calculates precision, recall, F1 score, and accuracy based on predicted and true labels.
    */

    var true_positives: Int64
    var false_positives: Int64
    var false_negatives: Int64
    var true_negatives: Int64

    public init() {
        /*
        Initialize the number of all four samples to 0
        */
        this.true_positives = 0
        this.false_positives = 0
        this.false_negatives = 0
        this.true_negatives = 0
    }

    public func update(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Unit {
        /*
        Update the number of all four samples(true_positives, false_positives, false_negatives, true_negatives)
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: None, change the number of corresponding samples
        >>> mc = MetricsCalculator()
        >>> mc.update(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        (this.true_positives, this.false_positives, this.false_negatives, this.true_negatives) = (1, 1, 1, 1)
        */
        let len = predicted_labels.size()
        for (i in 0..len) {
            let p = predicted_labels[i]
            let t = true_labels[i]
            if (p == 1 && t == 1) {
                this.true_positives += 1
            } else if (p == 1 && t == 0) {
                this.false_positives += 1
            } else if (p == 0 && t == 1) {
                this.false_negatives += 1
            } else {
                this.true_negatives += 1
            }
        }
    }

    public func precision(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate precision
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.precision(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        var tp = 0
        var fp = 0
        let len = predicted_labels.size()
        for (i in 0..len) {
            let p = predicted_labels[i]
            let t = true_labels[i]
            if (p == 1 && t == 1) {
                tp += 1
            } else if (p == 1 && t == 0) {
                fp += 1
            }
        }
        if (tp + fp == 0) {
            return 0.0
        }
        return Float64(tp) / Float64(tp + fp)
    }

    public func recall(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate recall
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.recall(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        var tp = 0
        var fn = 0
        let len = predicted_labels.size()
        for (i in 0..len) {
            let p = predicted_labels[i]
            let t = true_labels[i]
            if (p == 1 && t == 1) {
                tp += 1
            } else if (p == 0 && t == 1) {
                fn += 1
            }
        }
        if (tp + fn == 0) {
            return 0.0
        }
        return Float64(tp) / Float64(tp + fn)
    }

    public func f1_score(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate f1 score, which is the harmonic mean of precision and recall
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.f1_score(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        let p = this.precision(predicted_labels, true_labels)
        let r = this.recall(predicted_labels, true_labels)
        if (p + r == 0.0) {
            return 0.0
        }
        return 2.0 * p * r / (p + r)
    }

    public func accuracy(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate accuracy
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.accuracy(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        var correct = 0
        let len = predicted_labels.size()
        for (i in 0..len) {
            if (predicted_labels[i] == true_labels[i]) {
                correct += 1
            }
        }
        return Float64(correct) / Float64(len)
    }
}

import std.collection.ArrayList
import std.math.abs

class MetricsCalculator2 {

    public init() {}

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        let results = ArrayList<(ArrayList<Int64>, Int64)>()
        if (data is (ArrayList<Int64>, Int64)) {
            results.append(data)
        } else if (data is ArrayList<(ArrayList<Int64>, Int64)>) {
            results = data
        } else {
            return (0.0, ArrayList<Float64>())
        }

        let mrrs = ArrayList<Float64>()
        for (preds, total) in results {
            var rank = -1
            for (i, p) in preds {
                if (p == 1) {
                    rank = i + 1
                    break
                }
            }
            let rr = (rank == -1) ? 0.0 : 1.0 / Float64(rank)
            mrrs.append(rr)
        }

        let avg = mrrs.fold(0.0, (a, b) => a + b) / Float64(mrrs.size())
        return (avg, mrrs)
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        let results = ArrayList<(ArrayList<Int64>, Int64)>()
        if (data is (ArrayList<Int64>, Int64)) {
            results.append(data)
        } else if (data is ArrayList<(ArrayList<Int64>, Int64)>) {
            results = data
        } else {
            return (0.0, ArrayList<Float64>())
        }

        let aps = ArrayList<Float64>()
        for (preds, total) in results {
            var correct = 0
            var cumPrecision = 0.0
            for (i, p) in preds {
                if (p == 1) {
                    correct += 1
                    cumPrecision += Float64(correct) / Float64(i + 1)
                }
            }
            let ap = (correct == 0) ? 0.0 : cumPrecision / Float64(total)
            aps.append(ap)
        }

        let avg = aps.fold(0.0, (a, b) => a + b) / Float64(aps.size())
        return (avg, aps)
    }
}

import std.collection.ArrayList
import std.random.Random
import std.convert.*

class MinesweeperGame {

    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        var grid = ArrayList<ArrayList<Int64>>()
        var result = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            grid.append(ArrayList<Int64>())
            result.append(ArrayList<String>())
            for (j in 0..n) {
                grid[i].append(0)
                result[i].append("0")
            }
        }
        var rng = Random()
        var placed = 0
        while (placed < k) {
            let x = rng.nextInt64() % n
            let y = rng.nextInt64() % n
            if (grid[x][y] != -1) {
                grid[x][y] = -1
                result[x][y] = "X"
                for (dx in -1..2) {
                    for (dy in -1..2) {
                        let nx = x + dx
                        let ny = y + dy
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && grid[nx][ny] != -1) {
                            grid[nx][ny] += 1
                            result[nx][ny] = grid[nx][ny].toString()
                        }
                    }
                }
                placed += 1
            }
        }
        return result
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        var map = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            map.append(ArrayList<String>())
            for (j in 0..n) {
                map[i].append("-")
            }
        }
        return map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for (i in 0..n) {
            for (j in 0..n) {
                if (minesweeper_map[i][j] != "X" && map[i][j] == "-") {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if (x < 0 || x >= n || y < 0 || y >= n) {
            return player_map
        }
        if (player_map[x][y] != "-") {
            return player_map
        }
        if (minesweeper_map[x][y] == "X") {
            return false
        }
        player_map[x][y] = minesweeper_map[x][y]
        score += 1
        if (check_won(player_map)) {
            return true
        }
        return player_map
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.time.DateTime
import std.math.abs

class MovieBookingSystem {

    let movies: ArrayList<HashMap<String, Any>>

    public init() {
        movies = ArrayList<HashMap<String, Any>>()
    }

    public func add_movie(name: String, price: Float64, start_time: String, end_time: String, n: Int64): Unit {
        let seats = ArrayList<ArrayList<Int64>>()
        for (_ in 0..n) {
            let row = ArrayList<Int64>()
            for (_ in 0..n) {
                row.append(0)
            }
            seats.append(row)
        }
        let movie = HashMap<String, Any>()
        movie["name"] = name
        movie["price"] = price
        movie["start_time"] = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        movie["end_time"] = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")
        movie["seats"] = seats
        movies.append(movie)
    }

    public func book_ticket(name: String, seats_to_book: ArrayList<ArrayList<Int64>>): String {
        for (movie in movies) {
            if (movie["name"] as String == name) {
                let seats = movie["seats"] as ArrayList<ArrayList<Int64>>
                for (seat in seats_to_book) {
                    let r = seat[0]
                    let c = seat[1]
                    if (r < 0 || r >= seats.size() || c < 0 || c >= seats[0].size() || seats[r][c] != 0) {
                        return "Booking failed."
                    }
                }
                for (seat in seats_to_book) {
                    let r = seat[0]
                    let c = seat[1]
                    seats[r][c] = 1
                }
                return "Booking success."
            }
        }
        return "Movie not found."
    }

    public func available_movies(start_time: String, end_time: String): ArrayList<String> {
        let result = ArrayList<String>()
        let start = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let end = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")
        for (movie in movies) {
            let movieStart = movie["start_time"] as DateTime
            let movieEnd = movie["end_time"] as DateTime
            if (movieStart >= start && movieEnd <= end) {
                result.append(movie["name"] as String)
            }
        }
        return result
    }
}

import std.random.Random
import std.collection.ArrayList

class MusicPlayer {

    var playlist: ArrayList<String>
    var current_song: Option<String>
    var volume: Int64

    public init() {
        this.playlist = ArrayList<String>()
        this.current_song = None
        this.volume = 50
    }

    public func add_song(song: String): Unit {
        this.playlist.append(song)
    }

    public func remove_song(song: String): Unit {
        let index = this.playlist.indexOf(song)
        if (index >= 0) {
            this.playlist.remove(index)
            if (this.current_song == Some(song)) {
                this.current_song = None
            }
        }
    }

    public func play(): Option<String> {
        if (this.playlist.size() == 0) {
            return None
        }
        if (this.current_song == None) {
            this.current_song = Some(this.playlist[0])
        }
        return this.current_song
    }

    public func stop(): Bool {
        if (this.current_song != None) {
            this.current_song = None
            return true
        }
        return false
    }

    public func switch_song(): Bool {
        if (this.playlist.size() == 0 || this.current_song == None) {
            return false
        }
        let current = this.current_song.get()
        let index = this.playlist.indexOf(current)
        if (index + 1 < this.playlist.size()) {
            this.current_song = Some(this.playlist[index + 1])
            return true
        }
        return false
    }

    public func previous_song(): Bool {
        if (this.playlist.size() == 0 || this.current_song == None) {
            return false
        }
        let current = this.current_song.get()
        let index = this.playlist.indexOf(current)
        if (index - 1 >= 0) {
            this.current_song = Some(this.playlist[index - 1])
            return true
        }
        return false
    }

    public func set_volume(volume: Int64): Bool {
        if (volume >= 0 && volume <= 100) {
            this.volume = volume
            return true
        }
        return false
    }

    public func shuffle(): Bool {
        if (this.playlist.size() == 0) {
            return false
        }
        let rand = Random()
        var n = this.playlist.size()
        for (i in 0..n) {
            let j = rand.nextInt(n - i) + i
            let temp = this.playlist[i]
            this.playlist[i] = this.playlist[j]
            this.playlist[j] = temp
        }
        return true
    }
}

