import std.convert.*

class NumberWordFormatter {

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
    }

    public func format(x: Option<String>): String {
        match (x) {
            case Some(s) => format_string(s)
            case None => "ZERO ONLY"
        }
    }

    public func format_string(x: String): String {
        if (x == "") {
            return "ZERO ONLY"
        }
        let parts = x.split(".")
        let integerPart = parts[0]
        var words = trans_integer(integerPart)
        if (parts.size() > 1) {
            let decimalPart = parts[1]
            if (decimalPart != "") {
                words += " POINT " + trans_decimal(decimalPart)
            }
        }
        words += " ONLY"
        words
    }

    func trans_integer(s: String): String {
        if (s == "0") {
            return "ZERO"
        }
        let n = s.size()
        var res = ""
        var i = 0
        while (i < n) {
            let remain = n - i
            let chunk = if (remain >= 3) {
                s[i..i+3]
            } else {
                s[i..]
            }
            let chunkWords = if (chunk.size() == 3) {
                trans_three(chunk)
            } else if (chunk.size() == 2) {
                trans_two(chunk)
            } else {
                trans_one(chunk)
            }
            if (chunkWords != "") {
                let magnitude = (remain - 1) / 3
                let suffix = parse_more(magnitude)
                res = if (res == "") {
                    chunkWords + (if (suffix != "") " " + suffix else "")
                } else {
                    chunkWords + (if (suffix != "") " " + suffix + " " else " ") + res
                }
            }
            i += chunk.size()
        }
        res
    }

    func trans_decimal(s: String): String {
        var res = ""
        for (c in s) {
            let digit = Int64.parse(c.toString())
            res += NUMBER[digit] + " "
        }
        res.trim()
    }

    func trans_one(s: String): String {
        if (s == "" || s == "0") {
            return ""
        }
        NUMBER[Int64.parse(s)]
    }

    public func trans_two(s: String): String {
        let n = Int64.parse(s)
        if (n < 10) {
            return NUMBER[n]
        } else if (n < 20) {
            return NUMBER_TEEN[n - 10]
        } else {
            let ten = n / 10
            let one = n % 10
            let tenWord = NUMBER_TEN[ten - 1]
            let oneWord = NUMBER[one]
            if (oneWord == "") {
                tenWord
            } else {
                tenWord + " " + oneWord
            }
        }
    }

    public func trans_three(s: String): String {
        let hundred = Int64.parse(s[0].toString())
        let rest = s[1..]
        var res = ""
        if (hundred > 0) {
            res += NUMBER[hundred] + " HUNDRED"
            let restWords = trans_two(rest)
            if (restWords != "") {
                res += " AND " + restWords
            }
        } else {
            res = trans_two(rest)
        }
        res
    }

    public func parse_more(i: Int64): String {
        if (i < NUMBER_MORE.size()) {
            NUMBER_MORE[i]
        } else {
            ""
        }
    }
}

import std.collection.ArrayList
import std.convert.*

class NumericEntityUnescaper {
    public init() {}

    public func replace(string: String): String {
        let len = string.size
        var res = StringBuilder()
        var i = 0
        while (i < len) {
            if (string[i] == '&' && i + 1 < len) {
                if (string[i + 1] == '#') {
                    var isHex = false
                    var start = i + 2
                    if (start < len && string[start] == 'x') {
                        isHex = true
                        start += 1
                    }
                    if (start >= len) {
                        res.append(string[i])
                        i += 1
                        continue
                    }
                    var j = start
                    while (j < len && isHex ? isHexChar(string[j]) : string[j].isDigit()) {
                        j += 1
                    }
                    if (j < len && string[j] == ';') {
                        let numStr = string[start..j]
                        let num = isHex ? Int64.parseRadix(numStr, 16) : Int64.parse(numStr)
                        if (num >= 0 && num <= 0x10FFFF) {
                            res.append(Rune(num.toUInt32()).toString())
                            i = j + 1
                            continue
                        }
                    }
                }
            }
            res.append(string[i])
            i += 1
        }
        res.toString()
    }

    public static func isHexChar(char: Rune): Bool {
        (char >= '0' && char <= '9') || (char >= 'a' && char <= 'f') || (char >= 'A' && char <= 'F')
    }
}

