class PageUtil {
    let data: ArrayList<Int64>
    let page_size: Int64
    let total_items: Int64
    let total_pages: Int64

    public init(data: ArrayList<Int64>, page_size: Int64) {
        this.data = data
        this.page_size = page_size
        this.total_items = data.size
        this.total_pages = (this.total_items + page_size - 1) / page_size
    }

    public func get_page(page_number: Int64): ArrayList<Int64> {
        if (page_number < 1 || page_number > total_pages) {
            return ArrayList<Int64>()
        }
        let start = (page_number - 1) * page_size
        let end = min(start + page_size, total_items)
        let page_data = ArrayList<Int64>()
        for (i in start..end) {
            page_data.append(data[i])
        }
        return page_data
    }

    public func get_page_info(page_number: Int64): Option<PageInfo> {
        if (page_number < 1 || page_number > total_pages) {
            return Option<PageInfo>(None)
        }
        let current_page = page_number
        let per_page = page_size
        let total_pages = this.total_pages
        let total_items = this.total_items
        let has_previous = current_page > 1
        let has_next = current_page < total_pages
        let page_data = get_page(current_page)
        return Option<PageInfo>(Some(PageInfo(current_page, per_page, total_pages, total_items, has_previous, has_next, page_data)))
    }

    public func search(keyword: String): SearchInfo {
        let results = ArrayList<Int64>()
        for (item in data) {
            if (item.toString().contains(keyword)) {
                results.append(item)
            }
        }
        let total_results = results.size
        let total_pages = (total_results + page_size - 1) / page_size
        return SearchInfo(keyword, total_results, total_pages, results)
    }
}

