import std.regex.Regex
import std.collection.ArrayList

class RegexUtils {

    public func match_regex(pattern: String, text: String): Bool {
        let re = Regex(pattern)
        return re.isMatch(text)
    }

    public func findall(pattern: String, text: String): ArrayList<String> {
        let re = Regex(pattern)
        let matches = re.matchAll(text)
        let results = ArrayList<String>()
        for (m in matches) {
            results.append(m.group(0))
        }
        return results
    }

    public func split(pattern: String, text: String): ArrayList<String> {
        let re = Regex(pattern)
        let parts = re.split(text)
        let results = ArrayList<String>()
        for (p in parts) {
            results.append(p)
        }
        return results
    }

    public func sub(pattern: String, replacement: String, text: String): String {
        let re = Regex(pattern)
        return re.replace(text, replacement)
    }

    public func generate_email_pattern(): String {
        return r"\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b"
    }

    public func generate_phone_number_pattern(): String {
        return r"\b\d{3}-\d{3}-\d{4}\b"
    }

    public func generate_split_sentences_pattern(): String {
        return r"[.!?][\s]{1,2}(?=[A-Z])"
    }

    public func split_sentences(text: String): ArrayList<String> {
        let pattern = generate_split_sentences_pattern()
        let re = Regex(pattern)
        let parts = re.split(text)
        let results = ArrayList<String>()
        for (i in 0..parts.size) {
            if (i == parts.size - 1) {
                results.append(parts[i])
            } else {
                results.append(parts[i].trimEnd{p => p == '.' || p == '!' || p == '?'})
            }
        }
        return results
    }

    public func validate_phone_number(phone_number: String): Bool {
        let pattern = generate_phone_number_pattern()
        return match_regex(pattern, phone_number)
    }

    public func extract_email(text: String): ArrayList<String> {
        let pattern = generate_email_pattern()
        return findall(pattern, text)
    }
}

class RPGCharacter {

    let name: String
    var hp: Int64
    var attack_power: Int64
    var defense: Int64
    var level: Int64
    var exp: Int64

    public init(name: String, hp: Int64, attack_power: Int64, defense: Int64, level!: Int64 = 1) {
        this.name = name
        this.hp = hp
        this.attack_power = attack_power
        this.defense = defense
        this.level = level
        this.exp = 0
    }

    public func attack(other_character: RPGCharacter): Unit {
        let dmg = this.attack_power - other_character.defense
        other_character.hp = other_character.hp - (dmg > 0 ? dmg : 1)
    }

    public func heal(): Int64 {
        this.hp = this.hp + 10
        if (this.hp > 100) {
            this.hp = 100
        }
        this.hp
    }

    public func gain_exp(amount: Int64): Unit {
        var remaining = amount
        while (remaining > 0 && this.level < 100) {
            let needed = this.level * 100 - this.exp
            if (remaining >= needed) {
                remaining = remaining - needed
                this.exp = 0
                this.level_up()
            } else {
                this.exp = this.exp + remaining
                remaining = 0
            }
        }
    }

    public func level_up(): (Int64, Int64, Int64, Int64) {
        if (this.level == 100) {
            return (this.level, this.hp, this.attack_power, this.defense)
        }
        this.level = this.level + 1
        this.hp = this.hp + 20
        this.attack_power = this.attack_power + 5
        this.defense = this.defense + 5
        this.exp = 0
        (this.level, this.hp, this.attack_power, this.defense)
    }

    public func is_alive(): Bool {
        this.hp > 0
    }
}

