import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        if (data.size() == 0) {
            return 0.0
        }
        let sorted = ArrayList<Int64>(data)
        sort(sorted, (a: Int64, b: Int64) => a < b)
        let n = sorted.size()
        if (n % 2 == 1) {
            return Float64(sorted[n / 2])
        } else {
            return (Float64(sorted[n / 2 - 1]) + Float64(sorted[n / 2])) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let freq = HashMap<Int64, Int64>()
        var maxCount = 0
        for (v in data) {
            let c = freq.getOrDefault(v, 0) + 1
            freq[v] = c
            if (c > maxCount) {
                maxCount = c
            }
        }
        let modes = ArrayList<Int64>()
        for ((k, v) in freq) {
            if (v == maxCount) {
                modes.append(k)
            }
        }
        sort(modes, (a: Int64, b: Int64) => a < b)
        return modes
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size() == 0) {
            return None
        }
        var sum = 0
        for (v in data) {
            sum += v
        }
        return Some(Float64(sum) / Float64(data.size()))
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let m = mean(data)
        if (m.isNone()) {
            return None
        }
        let meanVal = m.get()
        var sum = 0.0
        for (v in data) {
            let diff = Float64(v) - meanVal
            sum += diff * diff
        }
        return Some(sqrt(sum / Float64(data.size())))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let m = mean(data)
        let std = standard_deviation(data)
        if (m.isNone() || std.isNone()) {
            return None
        }
        let meanVal = m.get()
        let stdVal = std.get()
        if (stdVal == 0.0) {
            return None
        }
        let zs = ArrayList<Float64>()
        for (v in data) {
            zs.append((Float64(v) - meanVal) / stdVal)
        }
        return Some(zs)
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size() == 0 || x.size() != y.size()) {
            return None
        }
        let n = x.size()
        var sumX = 0
        var sumY = 0
        var sumXY = 0
        var sumX2 = 0
        var sumY2 = 0
        for (i in 0..n) {
            let xi = x[i]
            let yi = y[i]
            sumX += xi
            sumY += yi
            sumXY += xi * yi
            sumX2 += xi * xi
            sumY2 += yi * yi
        }
        let num = Float64(n) * Float64(sumXY) - Float64(sumX) * Float64(sumY)
        let den = sqrt(Float64(n * sumX2 - sumX * sumX)) * sqrt(Float64(n * sumY2 - sumY * sumY))
        if (den == 0.0) {
            return None
        }
        return Some(num / den)
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let d = data.size()
        let mat = ArrayList<ArrayList<Float64>>()
        for (i in 0..d) {
            let row = ArrayList<Float64>()
            for (j in 0..d) {
                row.append(Statistics3.correlation(data[i], data[j]).getOrElse(0.0))
            }
            mat.append(row)
        }
        return mat
    }
}

