import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs

class TriCalculator {

    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        let rad = x * PI / 180.0
        return taylor(rad, 50)
    }

    public func factorial(a: Int64): Decimal {
        var res = Decimal(1)
        for (i in 1..a+1) {
            res = res * Decimal(i)
        }
        return res
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        var sum: Float64 = 0.0
        var term: Float64 = 1.0
        var sign = 1
        for (k in 0..n) {
            sum += term * Float64(sign)
            term = term * x * x / Float64((2*k+1)*(2*k+2))
            sign = -sign
        }
        return sum
    }

    public func sin(x: Float64): Float64 {
        let rad = x * PI / 180.0
        var sum: Float64 = 0.0
        var term: Float64 = rad
        var sign = 1
        for (k in 0..50) {
            sum += term * Float64(sign)
            term = term * rad * rad / Float64((2*k+2)*(2*k+3))
            sign = -sign
        }
        return sum
    }

    public func tan(x: Float64): Option<Float64> {
        let c = cos(x)
        if (abs(c - 0.0) <= 0.000001) {
            return None
        }
        return Option<Float64>(Some(sin(x) / c))
    }
}

