class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        let dot = 0.0
        let norm1 = 0.0
        let norm2 = 0.0
        for (i in 0..vector_1.size()) {
            dot += vector_1[i] * vector_2[i]
            norm1 += vector_1[i] * vector_1[i]
            norm2 += vector_2[i] * vector_2[i]
        }
        return dot / (sqrt(norm1) * sqrt(norm2))
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for (v in vectors_all) {
            result.append(similarity(vector_1, v))
        }
        return result
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        let mean1 = array_mean(vector_list_1)
        let mean2 = array_mean(vector_list_2)
        return similarity(mean1, mean2)
    }

    private static func array_mean(vectors: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let dim = vectors[0].size()
        let mean = ArrayList<Float64>()
        for (i in 0..dim) {
            mean.append(0.0)
        }
        for (v in vectors) {
            for (i in 0..dim) {
                mean[i] += v[i]
            }
        }
        for (i in 0..dim) {
            mean[i] /= Float64(vectors.size())
        }
        return mean
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result = HashMap<String, Float64>()
        for ((k, v) in number_dict) {
            let count = v
            let idf = log(Float64(total_num + 1) / (count + 1.0))
            result[k] = idf
        }
        return result
    }
}

